struct Node;
struct TaggedPtr {
  Node* ptr; std::uint64_t tag;
};
using AT = std::atomic<TaggedPtr>;
using AU = std::atomic<std::uint64_t>;
std::cout << sizeof(TaggedPtr) << ' '
  << std::boolalpha
  << AT::is_always_lock_free << ' '
  << AU::is_always_lock_free;

struct Head {         // 8 bytes
  std::uint32_t idx;  // pool index
  std::uint32_t tag;
};
static_assert(
  std::atomic<Head>::is_always_lock_free);
